import{_ as a,C as o,o as s,c as i,j as e,a as n,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const b=JSON.parse(`{"title":"Write, run and fix a test","description":"The loop from a new Playwright spec to a passing test across Piwi's tools: record it from the editor or the browser, run it with Piwi, stop it at a breakpoint, write the fix at the stop, and debug a failure from its page.","frontmatter":{"title":"Write, run and fix a test","description":"The loop from a new Playwright spec to a passing test across Piwi's tools: record it from the editor or the browser, run it with Piwi, stop it at a breakpoint, write the fix at the stop, and debug a failure from its page.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/write-run-fix.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/write-run-fix.html"}],["meta",{"property":"og:title","content":"Write, run and fix a test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The loop from a new Playwright spec to a passing test across Piwi's tools: record it from the editor or the browser, run it with Piwi, stop it at a breakpoint, write the fix at the stop, and debug a failure from its page."}]]},"headers":[],"relativePath":"features/write-run-fix.md","filePath":"features/write-run-fix.md","lastUpdated":1794652141000}`),l={name:"features/write-run-fix.md"};function u(p,t,f,c,g,w){const r=o("Needs");return s(),i("div",null,[t[0]||(t[0]=e("h1",{id:"write-run-and-fix-a-test",tabindex:"-1"},[n("Write, run and fix a test "),e("a",{class:"header-anchor",href:"#write-run-and-fix-a-test","aria-label":'Permalink to "Write, run and fix a test"'},"​")],-1)),h(r,{reporter:"",fixtures:""}),t[1]||(t[1]=d('<p>This page takes a new test from an empty spec to a passing run, and names the tool for each step. Each step has a page of its own; this one is the map. The editor does most of it, in VS Code or a JetBrains IDE; Piwi Picker, the browser extension, does the same steps from the browser, and the desktop app runs them on your machine without an editor.</p><h2 id="before-the-first-test" tabindex="-1">Before the first test <a class="header-anchor" href="#before-the-first-test" aria-label="Permalink to &quot;Before the first test&quot;">​</a></h2><ul><li><strong>The capture fixtures</strong> in your specs: a test that imports <code>test</code> from <code>@playwright/test</code> runs, but never stops at a breakpoint, and the run says so (<a href="/guide/capture-fixtures.html">Capture fixtures</a>).</li><li><strong>The editor extension</strong>, connected to your instance or to the desktop app (<a href="./editors.html">Editor extensions</a>, <a href="./editor-connection.html">Editor connection</a>).</li><li><strong>Optional:</strong> <a href="./extension.html">Piwi Picker</a>, paired with the editor, to pick and record in your everyday browser and follow runs in its <a href="./runs-window.html">Runs window</a>.</li></ul><h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>In the editor</th><th>Outside the editor</th><th>Read on</th></tr></thead><tbody><tr><td>Write the test</td><td><strong>Record a new test file…</strong>, or <strong>Record here…</strong> at the cursor</td><td>Piwi Picker&#39;s <strong>Record actions</strong>, then <strong>Send to editor</strong></td><td><a href="./editor-recording.html">Record tests from the editor</a>, <a href="./recorded-code.html">Recorded code</a></td></tr><tr><td>Run it</td><td><strong>Run with Piwi</strong> from the gutter, the Testing view or the test at the cursor; <strong>Verify ×3</strong></td><td>the desktop app&#39;s <strong>Re-run</strong> of tests</td><td><a href="./editor-runs.html">Runs from the editor</a>, <a href="./desktop-runs.html">Desktop app runs</a></td></tr><tr><td>Watch it</td><td>the status bar, and the run&#39;s page on the instance</td><td>the Runs window, and the page itself once you <strong>Watch</strong> at a stop</td><td><a href="./live-view.html">Live view of a run</a>, <a href="./runs-window.html">Runs window</a></td></tr><tr><td>Stop it</td><td>a breakpoint, <strong>Pause</strong>, <strong>Step</strong>, <strong>Run to cursor</strong></td><td>the pause bar in the test&#39;s page</td><td><a href="./editor-breakpoints.html">Breakpoints in the browser</a>, <a href="./editor-run-control.html">Pause and step from the editor</a></td></tr><tr><td>Fix it at the stop</td><td><strong>Pick a locator</strong>, <strong>Record here</strong>, <strong>Assert</strong>, <strong>Mock a request</strong></td><td><strong>Pick a locator</strong> and <strong>Record here</strong> from the pause bar; all four from the Runs window</td><td><a href="./editor-stop-code.html">Code from a pause</a></td></tr><tr><td>Debug a failure</td><td><strong>Debug in my editor</strong>, from the failure&#39;s page</td><td>the failure page&#39;s Locator fix</td><td><a href="./debug-in-editor.html">Debug in my editor</a>, <a href="./locator-healing.html">Locator healing</a></td></tr></tbody></table><h2 id="write-it" tabindex="-1">Write it <a class="header-anchor" href="#write-it" aria-label="Permalink to &quot;Write it&quot;">​</a></h2><p><strong>Record a new test file…</strong> offers the spec beside the one you are in, else in the config&#39;s <code>testDir</code>, and writes what you do in the browser as a test, with locators verified on the page and the page objects of your suite where they match. <strong>Record here</strong> writes steps at the cursor, in a test, a page object or a helper. A flow recorded in Piwi Picker lands at the cursor the same way through <strong>Send to editor</strong>: at the top level of a spec, as a new test.</p><h2 id="run-and-watch-it" tabindex="-1">Run and watch it <a class="header-anchor" href="#run-and-watch-it" aria-label="Permalink to &quot;Run and watch it&quot;">​</a></h2><p>A run Piwi starts reports to the instance like any other, with the run&#39;s origin. In a project that runs in CI, a failure seen only in developers&#39; own runs stays out of the team&#39;s inbox until someone shows it; one that fingerprints like a failure CI saw joins that cluster (<a href="./failure-clusters.html">Failure clusters &amp; the inbox</a>). A run you start in a terminal is followed too, when the editor is open: <a href="./terminal-runs.html">Runs started outside Piwi</a>.</p><h2 id="stop-it-and-write-the-fix-there" tabindex="-1">Stop it and write the fix there <a class="header-anchor" href="#stop-it-and-write-the-fix-there" aria-label="Permalink to &quot;Stop it and write the fix there&quot;">​</a></h2><p>Set a breakpoint on the line you are working on and run the test. It stops before that line&#39;s call, in a headed browser with Piwi&#39;s pause bar, or, headless, with the page shown in the editor. <strong>Pick a locator</strong>, <strong>Record here</strong>, <strong>Assert</strong> and <strong>Mock a request</strong> write their code where the stopped statement stands now, after the edits you made since the run started (<a href="./editor-stop-code.html">Code from a pause</a>); <strong>End the test</strong> skips the rest of it (<a href="./end-the-test.html">End the test</a>).</p><h2 id="when-it-fails" tabindex="-1">When it fails <a class="header-anchor" href="#when-it-fails" aria-label="Permalink to &quot;When it fails&quot;">​</a></h2><p>In a run Piwi started, a failing test holds its page where someone can see it (a headed browser, or while the Runs window is open), and the editor shows the failure as a stop, with the same actions. Otherwise its page on the instance explains it: the clues rank the likely cause, and the Locator fix panel offers the replacement locator. <strong>Debug in my editor</strong> on that page runs the failing test again from the editor and stops at the line it failed on.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editors.html">Editor extensions</a>: what the editor shows from your suite.</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a>: where failures land once they reach the team&#39;s runs.</li><li><a href="./agent-run-control.html">Run control for agents</a>: the same stops, steered by an agent.</li></ul>',15))])}const x=a(l,[["render",u]]);export{b as __pageData,x as default};
